const raw = $input.first().json;
const prepared = $('Validate Newsletter Send').first().json;
const requestedVersions = Array.isArray(prepared.versions) ? prepared.versions : [];
const customNote = String(prepared.custom_note || '').trim();

if (!requestedVersions.length) {
  throw new Error('No requested versions found after validation. Aborting before subscriber send.');
}

function findText(value, depth = 0) {
  if (value == null || depth > 6) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(v => findText(v, depth + 1)).find(Boolean) || '';
  if (typeof value === 'object') {
    for (const key of ['data', 'body', 'content', 'text', 'raw']) {
      const found = findText(value[key], depth + 1);
      if (found) return found;
    }
  }
  return '';
}

function normalizeText(text) {
  return String(text || '')
    .replace(/\\n/g, '\n')
    .replace(/\r\n/g, '\n');
}

function cleanNote(line) {
  return String(line || '')
    .replace(/^[-*]\s+/, '')
    .replace(/^•\s+/, '')
    .replace(/`/g, '')
    .trim();
}

function isVersionHeading(line, version) {
  const escaped = version.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`^\\s*(?:#{1,6}\\s*)?v?${escaped}\\s*$`, 'i').test(line);
}

function parseSections(text) {
  const lines = normalizeText(text).split('\n');
  const sections = {};
  let current = null;
  for (const rawLine of lines) {
    const line = rawLine.trim();
    const heading = line.match(/^(?:#{1,6}\s*)?v?(\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?)\s*$/i);
    if (heading) {
      current = heading[1];
      if (!sections[current]) sections[current] = [];
      continue;
    }
    if (!current) continue;
    const note = cleanNote(line);
    if (!note || /^[-*_]{3,}$/.test(note)) continue;
    sections[current].push(note);
  }
  return sections;
}

function findMarkdownSection(text, version) {
  const lines = normalizeText(text).split('\n');
  let capture = false;
  const notes = [];
  for (const rawLine of lines) {
    const line = rawLine.trim();
    const anyVersionHeading = /^(?:#{1,6}\s*)?v?\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?\s*$/i.test(line);
    if (isVersionHeading(line, version)) { capture = true; continue; }
    if (capture && anyVersionHeading) break;
    if (!capture) continue;
    const note = cleanNote(line);
    if (!note || /^[-*_]{3,}$/.test(note)) continue;
    notes.push(note);
  }
  return notes;
}

const readmeText = normalizeText(findText(raw) || JSON.stringify(raw));
const manualText = normalizeText(customNote);
const manualSections = parseSections(manualText);
const sections = [];
const missing = [];
for (const version of requestedVersions) {
  let notes = manualSections[version] || [];
  if (!notes.length) notes = findMarkdownSection(readmeText, version);
  if (!notes.length) missing.push(version);
  else sections.push({ version, notes });
}
if (missing.length) {
  throw new Error(`Requested changelog version(s) not found in manual_changelog or README: ${missing.join(', ')}. Aborting before subscriber send.`);
}

function versionLabel(versions) {
  if (versions.length === 1) return versions[0];
  return versions.join(' + ');
}
function sentence(s) {
  const t = String(s || '').trim();
  return t ? t.charAt(0).toUpperCase() + t.slice(1).replace(/[.!?]?$/, '.') : '';
}
function classify(note) {
  const l = note.toLowerCase();
  if (/(security|privacy|permission|auth|login|token)/.test(l)) return { title: 'Security and access', explanation: sentence(note), importance: 100 };
  if (/(new|add|feature|support|enable|introduce)/.test(l)) return { title: 'New capability', explanation: sentence(note), importance: 90 };
  if (/(fix|bug|issue|error|crash|broken)/.test(l)) return { title: 'Fixes', explanation: sentence(note), importance: 80 };
  if (/(ui|design|layout|screen|button|form|menu|copy)/.test(l)) return { title: 'User interface', explanation: sentence(note), importance: 70 };
  if (/(performance|speed|cache|load|slow)/.test(l)) return { title: 'Performance', explanation: sentence(note), importance: 60 };
  return { title: 'Release note', explanation: sentence(note), importance: 50 };
}
const seen = new Set();
const editorialHighlights = [];
for (const section of sections) {
  for (const note of section.notes) {
    const h = classify(note);
    const key = `${h.title}:${h.explanation}`.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    editorialHighlights.push({ ...h, sources: [note] });
  }
}
editorialHighlights.sort((a, b) => b.importance - a.importance);

const label = versionLabel(requestedVersions);
const changelogRaw = sections.map(s => `v${s.version}\n${s.notes.map(n => `- ${n}`).join('\n')}`).join('\n\n');
const editorialBrief = [
  `Announce Your Product v${label}.`,
  'Write in English, concise and factual. Do not mention tests. Do not announce any version that is not listed below.',
  'Focus on user-visible changes first. Avoid generic marketing phrases; every sentence must map to a changelog item.'
].join('\n');

const releaseLinks = requestedVersions.map(v => ({
  version: v,
  url: `https://example.com/releases/v${v}`
}));

return [{ json: {
  version: requestedVersions[requestedVersions.length - 1],
  versions: requestedVersions,
  version_label: label,
  is_aggregated_release: requestedVersions.length > 1,
  custom_note: customNote,
  sections,
  editorial_highlights: editorialHighlights.slice(0, 6),
  editorial_brief: editorialBrief,
  changelog_raw: changelogRaw,
  release_links: releaseLinks,
  release_url: releaseLinks[releaseLinks.length - 1].url,
  website_url: 'https://example.com'
}}];

parameters.text:
=Version(s) to announce: {{ $json.version_label || $json.version }}
Included versions: {{ ($json.versions || [$json.version]).join(', ') }}

Editorial brief:
{{ $json.editorial_brief }}

Grouped changelog:
{{ $json.changelog_raw }}

Prepared highlights:
{{ JSON.stringify($json.editorial_highlights || []) }}

Write a subscriber release email in English. Keep it concrete and similar in tone to a polished test announcement: short intro, clear section-style highlights, no hype, no "test", no version outside the included versions. Return only the structured fields required by the parser.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "subject": { "type": "string", "description": "Short, direct email subject in English only. Mention the product and either the version label or the strongest concrete user-visible change. No generic marketing phrases." },
    "intro": { "type": "string", "description": "1-2 opening sentences in English only. Summarize the real user-visible change(s). If there are no meaningful user-visible changes, say this is a small maintenance update without hype." },
    "highlights": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Maximum 5 specific user-focused highlights in English only. Each item must say what changed and why it matters. No vague phrases like latest improvements, enhanced experience, seamless, or various fixes."
    },
    "closing": { "type": "string", "description": "Closing sentence in English only. State whether the user needs to do anything."
  } },
  "required": ["subject", "intro", "highlights", "closing"]
}

