const ai = $input.first().json.output || {};
const meta = $('Extract Requested Release Versions').first().json;

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const label = meta.version_label || meta.version;
const editorial = Array.isArray(meta.editorial_highlights) ? meta.editorial_highlights : [];
const sections = Array.isArray(meta.sections) ? meta.sections : [];

function splitHighlight(value) {
  const text = String(value || '').trim();
  const m = text.match(/^([^:]{3,70}):\s*(.+)$/);
  if (m) return { title: m[1].trim(), text: m[2].trim() };
  return { title: 'What changed', text };
}

const forbiddenPattern = /\b(test|testing|latest improvements|enhanced experience|seamless|powerful|various fixes|better performance|improved reliability|new version is available|overall experience)\b/i;
const combined = [ai.subject, ai.intro, ...(ai.highlights || []), ai.closing].filter(Boolean).join(' ');
const aiUsable = Array.isArray(ai.highlights)
  && ai.highlights.length > 0
  && !forbiddenPattern.test(combined)
  && ai.highlights.every(h => String(h || '').trim().length >= 25);

const fallbackHighlights = editorial.map(h => ({
  title: h.title || 'What changed',
  text: h.explanation || (Array.isArray(h.sources) ? h.sources[0] : '') || ''
})).filter(h => h.text).slice(0, 5);

const highlights = aiUsable ? ai.highlights.slice(0, 5).map(splitHighlight) : fallbackHighlights;
const safeSubject = aiUsable && ai.subject && !forbiddenPattern.test(ai.subject)
  ? ai.subject
  : `Your Product v${label}: ${highlights[0]?.title || 'release update'}`;
const safeIntro = aiUsable && ai.intro && !forbiddenPattern.test(ai.intro)
  ? ai.intro
  : `Your Product v${label} is now available. This email summarizes the user-visible changes included in the release.`;
const safeClosing = aiUsable && ai.closing && !forbiddenPattern.test(ai.closing)
  ? ai.closing
  : 'No manual action is needed unless your release notes say otherwise.';

const highlightsHtml = highlights.length
  ? highlights.map(h => `
      <tr>
        <td style="padding:14px 16px;border:1px solid #e5e7eb;border-radius:12px;background:#ffffff;">
          <div style="font-weight:700;color:#111827;margin-bottom:4px;">${escapeHtml(h.title)}</div>
          <div style="color:#374151;line-height:22px;">${escapeHtml(h.text)}</div>
        </td>
      </tr>
      <tr><td style="height:10px;font-size:10px;line-height:10px;">&nbsp;</td></tr>`).join('')
  : '';

const detailsHtml = sections.length
  ? `<h2 style="font-size:18px;margin:24px 0 10px;color:#111827;">Included changelog</h2>` + sections.map(section => `
      <div style="margin:0 0 14px 0;padding:14px 16px;border:1px solid #e5e7eb;border-radius:12px;background:#f9fafb;">
        <div style="font-weight:700;color:#111827;margin-bottom:8px;">v${escapeHtml(section.version)}</div>
        <ul style="margin:0;padding-left:20px;color:#374151;line-height:22px;">
          ${(section.notes || []).slice(0, 8).map(note => `<li>${escapeHtml(note)}</li>`).join('')}
        </ul>
      </div>`).join('')
  : '';

const html = `<!doctype html>
<html>
  <body style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;color:#111827;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f4f6;padding:24px 0;">
      <tr><td align="center">
        <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="width:640px;max-width:94%;background:#ffffff;border-radius:18px;overflow:hidden;border:1px solid #e5e7eb;">
          <tr><td style="padding:28px 32px;background:linear-gradient(135deg,#111827,#2563eb);color:#ffffff;">
            <div style="font-size:13px;letter-spacing:.08em;text-transform:uppercase;opacity:.85;">Release update</div>
            <h1 style="margin:8px 0 0 0;font-size:28px;line-height:34px;">Your Product v${escapeHtml(label)}</h1>
          </td></tr>
          <tr><td style="padding:28px 32px;">
            <p style="margin:0 0 18px 0;font-size:16px;line-height:24px;color:#374151;">${escapeHtml(safeIntro)}</p>
            <table role="presentation" width="100%" cellspacing="0" cellpadding="0">${highlightsHtml}</table>
            ${detailsHtml}
            <div style="margin:18px 0;padding:14px 16px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;color:#1e3a8a;line-height:22px;">${escapeHtml(safeClosing)}</div>
            <table role="presentation" cellspacing="0" cellpadding="0" style="margin-top:20px;"><tr>
              <td><a href="${escapeHtml(meta.website_url)}" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:11px 16px;border-radius:10px;font-weight:700;">Open the website</a></td>
              <td style="width:10px;">&nbsp;</td>
              <td><a href="${escapeHtml(meta.release_url)}" style="display:inline-block;background:#ffffff;color:#2563eb;text-decoration:none;padding:10px 15px;border-radius:10px;font-weight:700;border:1px solid #bfdbfe;">Release notes</a></td>
            </tr></table>
          </td></tr>
          <tr><td style="padding:18px 32px;background:#f9fafb;color:#6b7280;font-size:12px;line-height:18px;">
            You are receiving this because you subscribed to Your Product updates.<br>
            Replace this footer with your legal, privacy, and unsubscribe information.
          </td></tr>
        </table>
      </td></tr>
    </table>
  </body>
</html>`;

return [{ json: { subject: safeSubject, html, ai_used: aiUsable, quality_gate: aiUsable ? 'ai_passed' : 'deterministic_editorial_fallback', highlights_count: highlights.length, version_label: label } }];

