const input = $input.first().json;
const versionText = String(input.version || '').trim();
const confirm = String(input.SEND_EMAIL || '').trim();
const changelogText = String(input.changelog || '').trim();

function parseVersions(text) {
  const matches = String(text || '').match(/v?\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?/gi) || [];
